def glomit(self, target, scope):
    scope[MODE] = GROUP
    scope[CUR_AGG] = None  # reset aggregation tripwire for sub-specs
    scope[ACC_TREE] = {}

    # Initialize the accumulator for the spec
    if type(self.spec) in (dict, list):
        _spec_id = id(self.spec)
        scope[ACC_TREE][_spec_id] = type(self.spec)()

    for t in target_iter(target, scope):
        ret = scope[glom](t, self.spec, scope)
        if ret is STOP:
            break

    # Extract and return the accumulated result
    _spec_id = id(self.spec)
    if _spec_id in scope[ACC_TREE]:
        return scope[ACC_TREE][_spec_id]
    return ret
